CREATE TYPE "AuditStatus" AS ENUM ('QUEUED','VALIDATING','DISCOVERING','CRAWLING','LIGHTHOUSE','ANALYZING','COMPLETED','PARTIAL','FAILED');
CREATE TYPE "PaymentStatus" AS ENUM ('CREATED','APPROVED','CAPTURED','FAILED','REFUNDED');
CREATE TABLE "Audit" ("id" TEXT PRIMARY KEY,"normalizedUrl" TEXT NOT NULL,"domain" TEXT NOT NULL,"status" "AuditStatus" NOT NULL DEFAULT 'QUEUED',"locale" TEXT NOT NULL DEFAULT 'he',"questionnaire" JSONB NOT NULL,"overallScore" INTEGER,"categoryScores" JSONB,"publicSummary" JSONB,"fullReport" TEXT,"estimatedValue" JSONB,"promptVersion" TEXT NOT NULL DEFAULT 'audit-v1',"errorCode" TEXT,"startedAt" TIMESTAMP(3),"completedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "AuditPage" ("id" TEXT PRIMARY KEY,"auditId" TEXT NOT NULL REFERENCES "Audit"("id") ON DELETE CASCADE,"url" TEXT NOT NULL,"pageType" TEXT NOT NULL,"title" TEXT,"metadata" JSONB,"extractedContent" TEXT,"lighthouse" JSONB,"status" TEXT NOT NULL);
CREATE TABLE "Finding" ("id" TEXT PRIMARY KEY,"auditId" TEXT NOT NULL REFERENCES "Audit"("id") ON DELETE CASCADE,"auditPageId" TEXT REFERENCES "AuditPage"("id") ON DELETE SET NULL,"category" TEXT NOT NULL,"title" TEXT NOT NULL,"description" TEXT NOT NULL,"evidence" TEXT NOT NULL,"affectedUrl" TEXT NOT NULL,"severity" TEXT NOT NULL,"confidence" TEXT NOT NULL,"impactType" TEXT NOT NULL,"effort" TEXT NOT NULL,"recommendation" TEXT NOT NULL,"source" TEXT NOT NULL);
CREATE TABLE "Lead" ("id" TEXT PRIMARY KEY,"auditId" TEXT NOT NULL REFERENCES "Audit"("id") ON DELETE CASCADE,"name" TEXT NOT NULL,"phone" TEXT NOT NULL,"email" TEXT NOT NULL,"consentAt" TIMESTAMP(3) NOT NULL,"source" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Payment" ("id" TEXT PRIMARY KEY,"auditId" TEXT NOT NULL REFERENCES "Audit"("id") ON DELETE CASCADE,"provider" TEXT NOT NULL DEFAULT 'paypal',"providerOrderId" TEXT NOT NULL UNIQUE,"providerCaptureId" TEXT UNIQUE,"amount" DECIMAL(10,2) NOT NULL,"currency" TEXT NOT NULL,"status" "PaymentStatus" NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"capturedAt" TIMESTAMP(3));
CREATE TABLE "AuditEvent" ("id" TEXT PRIMARY KEY,"auditId" TEXT NOT NULL REFERENCES "Audit"("id") ON DELETE CASCADE,"type" TEXT NOT NULL,"payload" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX "AuditPage_auditId_url_key" ON "AuditPage"("auditId","url");
CREATE INDEX "Audit_domain_createdAt_idx" ON "Audit"("domain","createdAt");
CREATE INDEX "Finding_auditId_category_idx" ON "Finding"("auditId","category");
CREATE INDEX "Payment_auditId_status_idx" ON "Payment"("auditId","status");
CREATE INDEX "AuditEvent_auditId_createdAt_idx" ON "AuditEvent"("auditId","createdAt");
